def solve_nqueens_with_fixed(n, fixed):
    """Solve N-Queens with fixed queen positions using backtracking."""

    # fixed is a dict: row -> col
    solution = [None] * n

    # Place fixed queens
    for row, col in fixed.items():
        solution[row] = col

    # Verify fixed queens don't conflict with each other
    fixed_rows = list(fixed.keys())
    for i in range(len(fixed_rows)):
        for j in range(i+1, len(fixed_rows)):
            r1, c1 = fixed_rows[i], fixed[fixed_rows[i]]
            r2, c2 = fixed_rows[j], fixed[fixed_rows[j]]
            if c1 == c2:
                print(f"Conflict: rows {r1} and {r2} same column {c1}")
                return None
            if abs(r1-r2) == abs(c1-c2):
                print(f"Conflict: rows {r1},{r2} cols {c1},{c2} on same diagonal")
                return None

    print("Fixed queens verified - no conflicts among them")

    # Used columns and diagonals from fixed queens
    def is_safe(row, col, current_solution):
        for r in range(n):
            if current_solution[r] is not None and r != row:
                c = current_solution[r]
                if c == col:
                    return False
                if abs(r - row) == abs(c - col):
                    return False
        return True

    # Verify all fixed queens are safe with each other
    for row, col in fixed.items():
        # temporarily remove this queen and check
        solution[row] = None
        if not is_safe(row, col, solution):
            print(f"Fixed queen at ({row},{col}) conflicts!")
            return None
        solution[row] = col

    # Backtracking
    rows_to_fill = [r for r in range(n) if r not in fixed]

    def backtrack(idx):
        if idx == len(rows_to_fill):
            return True

        row = rows_to_fill[idx]

        # Get used columns and diagonals
        used_cols = set()
        used_diag1 = set()  # row - col
        used_diag2 = set()  # row + col

        for r in range(n):
            if solution[r] is not None:
                c = solution[r]
                used_cols.add(c)
                used_diag1.add(r - c)
                used_diag2.add(r + c)

        for col in range(n):
            if col not in used_cols and (row - col) not in used_diag1 and (row + col) not in used_diag2:
                solution[row] = col
                if backtrack(idx + 1):
                    return True
                solution[row] = None

        return False

    if backtrack(0):
        return solution
    return None

